import { optimizeLabelStackWithRegistry } from '../common/utils/optimize-label-stack-with-registry';
export function optimizeMarks(marks, reactUFOVersion, registry) {
  return marks.map(({
    labelStack,
    time,
    ...others
  }) => ({
    ...others,
    labelStack: labelStack && optimizeLabelStackWithRegistry(labelStack, reactUFOVersion, registry),
    time: Math.round(time)
  }));
}